package com.example.datetimelinear; import android.os.Bundle; import android.view.View; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; import java.text.SimpleDateFormat; import java.util.Calendar; import java.util.Date; import java.util.Locale; public class MainActivity extends AppCompatActivity { TextView tvNumericDate,tvTextualDate,tvCurrentTime; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);tvNumericDate=findViewById(R.id.tvNumericDate);tvTextualDate=findViewById(R.id.tvTextualDate);tvCurrentTime=findViewById(R.id.tvCurrentTime);} public void displayDateAndTime(View v){Date d=Calendar.getInstance().getTime();tvNumericDate.setText(new SimpleDateFormat("dd/MM/yyyy",Locale.getDefault()).format(d));tvTextualDate.setText(new SimpleDateFormat("EEEE, MMMM d",Locale.getDefault()).format(d));tvCurrentTime.setText(new SimpleDateFormat("hh:mm a",Locale.getDefault()).format(d));}}
